  }
  box(0,277,W,112,"#596970");
  box(0,386,W,154,"#87969a");
  line(0,388,W,388,"#c0c9c9",4);
  line(0,365,W,365,"#b2b9b5",2);
  for(let i=0;i<9;i++)
    ellipse(i*130+15,440+i%3*29,65,4,"#a6b5b8");

  // Bus shelter.
  box(195,173,181,12,"#344c59");
  box(207,185,7,205,"#415965");
  box(357,185,7,205,"#415965");
  box(217,191,136,152,"#819ba455");
  box(232,337,106,8,"#415965");
  box(241,345,6,42,"#415965");
  box(322,345,6,42,"#415965");
  box(395,150,5,239,"#415965");
  box(378,130,39,42,"#e0d9b9");
