function woman(t) {
  const walking=t>9;
  const p=Math.max(0,Math.min(1,(t-9)/3));
  const x=466+p*115, y=405-p*47, scale=1-p*.19;
  const laugh=t>=8 && t<9;
  const back=t>=9;
  const stride=walking?Math.sin((t-9)*12):0;
  const bob=walking?Math.abs(stride)*2: laugh?Math.sin(t*28)*2:0;

  c.save(); c.translate(x,y+bob); c.scale(scale,scale);
  ellipse(0,3,36,5,"#53666b66");
  // Coat reflection.
  c.save(); c.globalAlpha=.12;
  c.scale(1,-.4); box(-19,-67,38,61,"#da4942"); c.restore();

  // Yellow boots and dark leggings.
  function leg(dx,dy) {
    box(dx-5,-37,10,23,"#36454e");
    box(dx-8,-23+dy,15,23,"#f1c743");
    box(dx-8,-7+dy,23,8,"#f6ce46");
    box(dx-8,0+dy,23,3,"#9e8130");
