  leg(-13,stride*7); leg(13,-stride*7);

  // Tall red raincoat.
  c.fillStyle="#d94a43";
  c.beginPath(); c.moveTo(-21,-139);
  c.lineTo(20,-139); c.lineTo(30,-31);
  c.quadraticCurveTo(0,-24,-30,-31);
  c.closePath(); c.fill();
  line(-18,-130,-34,-72+stride*5,"#c6403b",14);
  line(18,-130,34,-72-stride*5,"#c6403b",14);
  ellipse(-34,-68+stride*5,6,7,"#e1b9a2");
  ellipse(34,-68-stride*5,6,7,"#e1b9a2");
  if(!back) {
    line(0,-129,0,-33,"#ee7970",2);
    for(let j=0;j<4;j++) ellipse(5,-113+j*21,2,2,"#793b39");
    line(-19,-137,0,-120,"#a93433",3);
    line(19,-137,0,-120,"#a93433",3);
  } else {
    c.strokeStyle="#b83b39"; c.lineWidth=2;
    c.beginPath(); c.arc(0,-134,15,0,Math.PI); c.stroke();
    line(0,-115,0,-35,"#c3413c",1);
  }

  // Identical chin-length silver bob.
  box(-6,-151,12,15,"#ddb39b");
  ellipse(0,-164,24,30,"#cbd0d3");
  box(-24,-168,48,31,"#cbd0d3");
  if(!back) {
    ellipse(1,-162,16,22,"#e4bfa9");
    c.fillStyle="#d4d9dc";
    c.beginPath(); c.moveTo(-24,-169);
    c.quadraticCurveTo(-17,-204,16,-187);
    c.quadraticCurveTo(28,-178,23,-149);
    c.lineTo(15,-155); c.lineTo(10,-178);
    c.quadraticCurveTo(-3,-169,-17,-173);
    c.lineTo(-17,-143); c.lineTo(-24,-141); c.fill();
