function bus(t) {
  if(t<4 || t>8) return;
  const p=(t-4)/4, x=1050-p*1900, y=247;
  c.save(); c.translate(x,y);
  box(0,0,575,127,"#bfccca");
  box(0,84,575,30,"#385d68");
  box(0,0,575,12,"#344e5a");
  for(let j=0;j<7;j++) {
    box(18+j*77,20,65,47,"#405c6a");
