function rain(t) {
  c.save(); c.globalAlpha=.4;
  for(let i=0;i<150;i++) {
    const x=(i*73+t*47)%1020-30;
    const y=(i*113+t*360)%580-20;
    line(x,y,x-6,y+16,"#d4e4eb",1);
