function draw(t) {
  scene(t);
  // The bus stays on the roadway behind the waiting woman.
  bus(t); woman(t); rain(t);
  if(t>=9) {
    c.save();
    c.globalAlpha=Math.min(1,(t-9)*2);
    c.shadowColor="#18303b"; c.shadowBlur=12;
    text("walk anyway",480,482,43,"#fff9ec");
