}
function frame(now) {
  let t=Math.min(12,(now-start)/1000);
  draw(t);
  if(recording && t>=12) {
    recording=false; held=true;
    recorder.stop();
  }
  if(!recording && !held && t>=12) start=now;
  requestAnimationFrame(frame);
}
let recorder;
button.onclick=()=>{
  if(!window.MediaRecorder || !canvas.captureStream) {
    status.textContent="Video export requires Chrome or Edge on desktop.";
    return;
  }
  const stream=canvas.captureStream(30);
  const options=["video/webm;codecs=vp9","video/webm;codecs=vp8",
    "video/webm"].find(x=>MediaRecorder.isTypeSupported(x));
  if(!options) {
    status.textContent="This browser cannot export WebM. Try Chrome or Edge.";
    stream.getTracks().forEach(x=>x.stop()); return;
  }
  recorder=new MediaRecorder(stream,
    {mimeType:options,videoBitsPerSecond:4000000});
  const chunks=[];
  recorder.ondataavailable=e=>{if(e.data.size) chunks.push(e.data)};
  recorder.onstop=()=>{
    const blob=new Blob(chunks,{type:options});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url; a.download="walk-anyway.webm"; a.click();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
    stream.getTracks().forEach(x=>x.stop());
    button.disabled=false;
    status.textContent="Finished — walk-anyway.webm downloaded.";
  };
  button.disabled=true; held=false;
  status.textContent="Rendering 12 seconds — keep this tab visible…";
  start=performance.now(); draw(0);
  recorder.start(); recording=true;
};
requestAnimationFrame(frame);
</script>
